const source = items[0]?.json;
if (!source || !Array.isArray(source.candidates)) {
  throw new Error('HOLD_INVALID_CANDIDATE_RESPONSE');
}
if (
  source.requested_limit !== 2 ||
  source.candidate_count !== 2 ||
  source.candidates.length !== 2 ||
  source.selection_hold_count !== 0 ||
  !Number.isInteger(source.selection_checked_count) ||
  source.selection_checked_count < 2
) {
  throw new Error('HOLD_CANARY_CANDIDATE_AGGREGATE');
}
const seen = new Set();
return source.candidates.map((candidate, index) => {
  const projectKey = String(candidate?.project_key || '').trim();
  if (
    !projectKey ||
    seen.has(projectKey) ||
    candidate?.profile_reason !== 'missing_profile'
  ) throw new Error('HOLD_INVALID_CANDIDATE_IDENTITY');
  seen.add(projectKey);
  return {
    json: {
      control: {
        project_key: projectKey,
        canary_run_id: 'profile-generator-canary-2026-08-12-v2',
        canary_slot: index + 1,
        candidate_identity_safe: true,
        rollback_prestate: 'missing_summary',
        requested_limit: source.requested_limit,
        candidate_count: source.candidate_count,
        selection_checked_count: source.selection_checked_count,
        selection_hold_count: source.selection_hold_count
      }
    },
    pairedItem: { item: 0 }
  };
});

return items.map((item, index) => {
  const row = item.json || {};
  const control = row.control || {};
  const route = row.route_response || {};
  const routeSafe = Boolean(
    control.candidate_identity_safe === true &&
    String(route.project_key || '') === String(control.project_key || '') &&
    route.decision === 'full' &&
    route.reason === 'no_profile' &&
    route.scope === 'all' &&
    route.existing_profile === null &&
    route.expected_summary_updated_at === null &&
    control.rollback_prestate === 'missing_summary'
  );
  return {
    json: {
      control: { ...control, rollback_prestate_verified: routeSafe, route_safe: routeSafe },
      route,
      route_safe: routeSafe,
      should_generate: routeSafe,
      reason: routeSafe ? 'route_ok' : 'route_not_canary_safe'
    },
    pairedItem: { item: index }
  };
});

